import{_ as i,o as t,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const m=JSON.parse('{"title":"3.4.7 Invite Agency Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-7-invite-agency-member/spec.md","filePath":"feature/agency-workspace/3-4-7-invite-agency-member/spec.md"}'),o={name:"feature/agency-workspace/3-4-7-invite-agency-member/spec.md"};function s(r,e,c,l,d,h){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="_3-4-7-invite-agency-member" tabindex="-1">3.4.7 Invite Agency Member <a class="header-anchor" href="#_3-4-7-invite-agency-member" aria-label="Permalink to &quot;3.4.7 Invite Agency Member&quot;">​</a></h1><p>&gt; V2 (2026-10-02): added the inline auto-suggest lookup and the CLIENT-profile-selection step on accept — see the new subsections below. Inviting a CLIENT now also happens from the dedicated Workspace Client screen (<code>/workspaces/:id/clients</code>, FR 3.3.3) using the same underlying <code>WorkspaceService.inviteMember</code> / <code>AgencyInvitation</code> mechanism described here; this spec covers both entry points since the role-CLIENT rules (BR-27, mandatory Workspace, accept flow) are identical either way.</p><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>The Owner/Manager of an Agency opens the Member list of that Agency (<code>/agencies/:agencyId/members</code>) or a workspace&#39;s Client list (<code>/workspaces/:id/clients</code>) and submits the Invite form.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency Owner (sender) and the invited person (who may not have an account yet).</li><li><strong>Purpose:</strong> Let the Owner bring another person into the Agency by email invitation, optionally pre-assigning that person to one Workspace with a role, so they can start working as soon as they accept.</li><li><strong>Interface:</strong> Member list page (<code>/agencies/:agencyId/members</code>) with an &quot;Invite member&quot; action — a form with a required email and optional invitee name, note, Workspace, role and expiry period. The person invited accepts through the link in the invitation email.</li><li><strong>Data Processing:</strong> The system confirms the caller is the Owner of the Agency, then checks the duplicate, pending-limit and Workspace rules, stores the invitation as PENDING with a unique token and an expiry time, and sends the invitation email with an accept link carrying that token. Accepting the invitation later turns the invited person into a Member of the Agency, and adds them to the chosen Workspace when one was pre-assigned.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Invite Member form:</p><ul><li>Email (required), invitee name, note, Workspace selector, role selector and expiry period (1–30 days, 30 by default).</li><li>When the role CLIENT is selected, a Workspace must also be selected before the form can be submitted.</li><li>On success a confirmation appears and the new PENDING invitation shows in the invitation table.</li></ul><p>Figure — Invite Client dialog (<code>/workspaces/:id/clients</code>, &quot;Add client&quot;):</p><ul><li>Email input only (no role/Workspace selector — both are implicit: role is always CLIENT, Workspace is the current one), optional note.</li><li>As the Owner/Manager types a valid email, two independent inline hints may appear, debounced: <ol><li>A generic &quot;this user already has an account&quot; hint (existing user-lookup, shared with the regular Invite Member form).</li><li>A CLIENT-specific hint from <code>GET /api/v1/agencies/{agencyId}/invite-lookup?email=</code> — shown only when the email is already an active CLIENT in another workspace of the <strong>same</strong> Agency. It names that workspace and explains that sending the invite will reuse the existing Client Profile link rather than create a separate one. No hint is shown if the email is a CLIENT only in a <em>different</em> Agency (cross-Agency data is never surfaced here).</li></ol></li><li>Submitting still goes through the same <code>WorkspaceService.inviteMember</code> / <code>AgencyInvitation</code> mechanism as the regular Invite Member form — the hint is informational only, not a shortcut that skips the invite step.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> Email of the invited person.</li><li><strong>Input optional:</strong> inviteeName (shown in the invitation email), note (message carried with the invitation), workspaceId (the Workspace to pre-assign; mandatory when role = CLIENT), role (MemberRole: MANAGER, CREATOR, CLIENT), expiryDays (integer 1–30, 30 by default).</li><li><strong>System data:</strong> Agency Owner identifier, the Agency Member records of the Agency (duplicate check), the PENDING invitations of the Agency (count and duplicate check), the invitation record — id, agencyId, agencyName, invitedEmail, invitedBy, token, note, workspaceId, workspaceName, role (nullable), status (InvitationStatus: PENDING, ACCEPTED, EXPIRED, REVOKED), expiresAt, acceptedAt (nullable), createdAt — and the Workspace record when one is pre-assigned.</li><li><strong>Output:</strong> The stored invitation, PENDING, carrying its token and expiry time; the invitation email sent to the invited person. No in-app notification is produced.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-27:</strong> Invite: only Owner/Manager-equivalent (here, the Agency Owner) may invite; an already-active member cannot be re-invited; a second invite is blocked while a pending, unexpired invitation exists for the same email; invitation token is a random UUID with an expiry window. Anybody other than the Owner is refused with <code>403 NOT_AGENCY_OWNER</code>.</li><li>The invited email must not already be a Member of the Agency; otherwise <code>409 ALREADY_AGENCY_MEMBER</code> (BR-27).</li><li>The invited email must not already hold a PENDING invitation for this Agency; otherwise <code>409 INVITATION_ALREADY_PENDING</code> (BR-27).</li><li>An Agency may hold at most 20 PENDING invitations that have not expired; beyond that, <code>409 TOO_MANY_PENDING_INVITATIONS</code>.</li><li>A Workspace sent with the invitation must belong to the same Agency; otherwise <code>400 WORKSPACE_NOT_IN_AGENCY</code>.</li><li>With the role MANAGER, the chosen Workspace must not already have an active manager, since a Workspace holds one manager only; otherwise <code>409 MANAGER_ALREADY_ASSIGNED</code>.</li><li>With the role CLIENT, a Workspace is mandatory from the moment of invitation; otherwise <code>400 WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code>. A Client does not become an Agency Member and needs a Workspace so that a Client Profile and a Workspace membership can be assigned on acceptance.</li><li><strong>(V2) Internal member cannot be invited as CLIENT:</strong> the &quot;already a Member of the Agency&quot; check (BR-27 above, <code>409 ALREADY_AGENCY_MEMBER</code>) applies uniformly to every role, including CLIENT — a person already on the Agency&#39;s internal roster (OWNER/MANAGER/MEMBER) cannot also be invited as that Agency&#39;s own client. No separate error code exists for this case; it is the same <code>ALREADY_AGENCY_MEMBER</code> check.</li><li><strong>(V2) Auto-suggest hint, not a hard rule:</strong> <code>GET /api/v1/agencies/{agencyId}/invite-lookup?email=</code> is read-only and advisory — it never blocks or auto-fills the submit. It returns <code>{ userExists, isAlreadyClientInAgency, existingWorkspaces[] }</code>, computed by resolving the email to a User, finding every <code>ClientProfile</code> they own, and checking whether any is linked (<code>workspace_members.client_profile_id</code>) to an active CLIENT membership in a workspace whose <code>agencyId</code> matches the current Agency. Workspaces of other Agencies are never included.</li><li><strong>(V2) Client Profile selection on accept:</strong> when accepting a CLIENT invitation, the invited person must choose — from <code>GET /api/v1/client-profile/mine</code> — one of the Client Profiles they already own, or submit a <code>newClientProfile</code> payload to create one inline. If they own none and submit neither, the accept is rejected with <code>400 CLIENT_PROFILE_REQUIRED_FOR_ACCEPT</code>. A profile chosen this way is not required to be new or Agency-specific — reusing a profile already linked to a workspace of a different Agency is allowed (Client Profiles are never Agency-scoped, FR 3.3.3 V2).</li><li>The expiry period is settable between 1 and 30 days and defaults to 30 days; a value outside that range is brought back inside it (BR-27, &quot;invitation token is a random UUID with an expiry window&quot;). <ul><li><strong>⚠ BA conflict (needs team decision):</strong> <code>docs/ba/03-agency-workspace-management.md</code> states a fixed 3-day expiry with no configurability. The current code (<code>AgencyServiceImpl.INVITATION_EXPIRY_DAYS</code>) implements 30 days, adjustable 1–30. This spec documents the code&#39;s actual behavior; the 3-day BA figure and the 30-day code figure disagree and have not been reconciled — do not change either side without a team decision on which number is authoritative.</li></ul></li><li>The invitation reaches the invited person by email only. No in-app notification is produced, because the system has no shared notification module yet.</li><li>On acceptance, an invited person with no role or a role other than CLIENT becomes an Agency Member at the MEMBER role — the Agency level knows only OWNER and MEMBER. When the invitation carried a Workspace and a role of MANAGER or CREATOR, the matching Workspace membership is created automatically at the same time.</li><li>On acceptance, an invited person with role CLIENT never becomes an Agency Member — they instead select or create a Client Profile (see the V2 bullet above) and are added directly to the pre-assigned Workspace as a CLIENT member linking that profile.</li><li>There is no automatic acceptance when somebody registers with the invited email address. The invited person must open the link, or accept with the token, themselves.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Email empty or malformed → Display: MSG02 / MSG04</li><li>Caller is not the Agency Owner → Display: MSG39</li><li>Email already a Member of the Agency → Display: MSG34</li><li>Email already holds a PENDING invitation for this Agency → Display: MSG35</li><li>Agency already holds 20 PENDING invitations → Display: MSG38 (closest fit — no dedicated MSG code for a pending-invitation cap)</li><li>Workspace does not exist → Display: MSG38</li><li>Workspace does not belong to this Agency → Display: MSG38 (closest fit — no dedicated MSG code for this case)</li><li>Role MANAGER but the Workspace already has an active manager → Display: MSG38 (closest fit — no dedicated MSG code for this case)</li><li>Role CLIENT without a Workspace → Display: MSG02 (closest fit — no dedicated MSG code for this case)</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Owner opens the Member list of an Agency and fills in the Invite Member form, with the email and any optional values.</li><li>The client submits the invitation.</li><li>The system confirms the caller is the Owner of the Agency.</li><li>The system rejects the invitation if the email already belongs to a Member, already holds a PENDING invitation, or the Agency has reached 20 PENDING invitations.</li><li>When a Workspace is sent, the system confirms it belongs to the Agency and that it holds no active manager if the role is MANAGER; when the role is CLIENT, the system confirms a Workspace was sent.</li><li>The system stores the invitation as PENDING with a unique token and the computed expiry time.</li><li>The system sends the invitation email, with an accept link carrying the token, without holding up the answer to the client.</li><li>The system returns the stored invitation and the client shows a confirmation and adds the row to the PENDING table; toast MSG33.</li><li>The invited person opens the accept link. When they have no account yet, they register and sign in first; the invitation is never accepted automatically.</li><li>The system confirms the token, the PENDING status, the unexpired expiry time and that the signed-in email matches the invited email, then records the person as an Agency Member at the MEMBER role, and adds the matching Workspace membership when the invitation carried a Workspace and a role of MANAGER or CREATOR.</li><li>The system marks the invitation ACCEPTED with the acceptance time and adds the person to the Agency.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>3.a1: Caller is not the Agency Owner (BR-27) → <code>403 NOT_AGENCY_OWNER</code>, toast MSG39; no invitation is stored. 3.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>4.a1: Email already a Member of the Agency (BR-27) → <code>409 ALREADY_AGENCY_MEMBER</code>, toast MSG34. 4.a2: The Owner picks a different email or reviews the existing member.</li><li>4.b1: Email already holds a PENDING invitation for this Agency (BR-27) → <code>409 INVITATION_ALREADY_PENDING</code>, toast MSG35. 4.b2: The Owner waits for that invitation to resolve or cancels it (3.4.8) before re-inviting.</li><li>4.c1: Agency already holds 20 PENDING invitations → <code>409 TOO_MANY_PENDING_INVITATIONS</code>, toast MSG38 (closest fit). 4.c2: The Owner cancels stale invitations (3.4.8) to free a slot, then resubmits.</li><li>5.a1: Workspace sent does not belong to this Agency → <code>400 WORKSPACE_NOT_IN_AGENCY</code>, toast MSG38 (closest fit). 5.a2: The Owner selects a Workspace that belongs to this Agency.</li><li>5.b1: Role MANAGER but the Workspace already has an active manager (BR-27, one-manager-per-workspace) → <code>409 MANAGER_ALREADY_ASSIGNED</code>, toast MSG38 (closest fit). 5.b2: The Owner chooses a different Workspace or role.</li><li>5.c1: Role CLIENT without a Workspace → <code>400 WORKSPACE_REQUIRED_FOR_CLIENT_INVITE</code>, Display: MSG02 (closest fit). 5.c2: The Owner selects a Workspace before submitting.</li><li>9.a1: The invited email has no account in the system yet → the invitation is still sent; no error. 9.a2: The person must register, sign in and accept the invitation themselves.</li><li>10.a1: The invitation expires before it is accepted → <code>400 INVALID_INVITATION</code> on acceptance, toast MSG38 (closest fit — no dedicated MSG code for an expired invitation); no Agency membership is created. 10.a2: The invited person asks the Owner to send a new invitation.</li><li>10.b1 (V2, CLIENT only): The invited person owns no Client Profile and submits neither <code>clientProfileId</code> nor <code>newClientProfile</code> → <code>400 CLIENT_PROFILE_REQUIRED_FOR_ACCEPT</code>, no Workspace membership is created. 10.b2: The accept screen requires them to pick an existing profile or fill the inline create-profile form before retrying.</li><li>10.c1 (V2, CLIENT only): <code>clientProfileId</code> is submitted but belongs to a different user → <code>403 CLIENT_PROFILE_NOT_OWNED</code>. 10.c2: The accept screen re-lists only the profiles the signed-in user actually owns.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>A PENDING invitation exists for the Agency, carrying its token, its expiry time and any pre-assigned Workspace and role, and the invitation email has been sent.</li><li>After acceptance: an Agency Member record at the MEMBER role exists for the invited person, and the invitation is ACCEPTED with its acceptance time; when the invitation carried a Workspace with the role MANAGER or CREATOR, the matching Workspace membership also exists.</li><li>After acceptance of a CLIENT invitation: no Agency Member record is created; a CLIENT <code>workspace_members</code> row exists in the pre-assigned Workspace, linking the Client Profile the invited person selected or created — the same profile they can keep reusing across any other Workspace/Agency.</li><li>No in-app notification is produced at any point.</li></ul>',25)])])}const u=i(o,[["render",s]]);export{m as __pageData,u as default};
